{
  "name": "recorded-test",
  "version": "1.0.0",
  "private": true,
  "description": "Playwright tests for Recorded Test",
  "scripts": {
    "test": "npx playwright test",
    "test:headed": "npx playwright test --headed",
    "test:ui": "npx playwright test --ui",
    "report": "npx playwright show-report"
  },
  "devDependencies": {
    "@playwright/test": "^1.52.0"
  }
}

import { defineConfig, devices } from '@playwright/test';

/**
 * Playwright configuration for Recorded Test.
 * Generated by CmdRunner from the Execution IR.
 */
export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: 'html',
  use: {
    baseURL: 'chrome-extension://gndjidfncanlhlonpcabokbdhnikglpn/src/sidepanel/index.html',
    viewport: { width: 780, height: 437 },
    trace: 'on-first-retry',
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] },
    },
  ],
});

import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Select Choose Sunday, September 6th, 2026 in the Depart on
    await page.getByLabel('Depart on').fill('Choose Sunday, September 6th, 2026')

    // Click the Churn
    await page.locator('#noop-churn').click()

    // Click the Search Flights
    await page.locator('[data-auto-id="search-flights"]').click()
    await expect.soft(page.locator('#result-count')).toContainText('1 selected')

    // Click the "Flights" link
    await page.locator('#nav-away').click()

    // Navigate to http://127.0.0.1:8191/flights?origin=MAA&dest=DEL&utm_source=test
    await page.goto('http://127.0.0.1:8191/flights?origin=MAA&dest=DEL&utm_source=test')
  });
});
